#!/usr/bin/env node
/**
 * PostToolUse(Edit|Write) hint — remind to lint after meaningful edit bursts.
 * Tracks edit counts in a temp file; every 10 edits suggests running lint.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');

const COUNTER = path.join(os.tmpdir(), 'zcode-edit-counter');
const THRESHOLD = 10;

try {
  let count = 0;
  try {
    count = parseInt(fs.readFileSync(COUNTER, 'utf8'), 10) || 0;
  } catch (_) {
    count = 0;
  }
  count += 1;
  fs.writeFileSync(COUNTER, String(count));

  if (count % THRESHOLD === 0) {
    console.log(
      `[post-edit-hint] ${count} edits this session. Suggestion: run \`bun run lint\` and tail dev.log to catch drift early.`
    );
  }
  process.exit(0);
} catch (err) {
  process.exit(0);
}

#!/usr/bin/env node
/**
 * PreToolUse(Bash) guard — block the classic footguns before they run.
 * Reads tool input from stdin: { tool_name, tool_input: { command } }
 * Exit code 2 = block the command; 0 = allow.
 */
let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => (raw += chunk));
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(raw || '{}');
    const command = (input.tool_input && input.tool_input.command) || '';

    const rules = [
      {
        test: /next\s+build|bun\s+run\s+build/,
        reason:
          'BLOCKED: `next build` is forbidden in this environment (dev server on port 3000 only). Use `bun run lint` for validation.',
      },
      {
        test: /rm\s+-rf\s+(\/|~|\$HOME)(\s|$)/,
        reason: 'BLOCKED: recursive delete of a root/home path. If you truly need this, run it manually after review.',
      },
      {
        test: /git\s+push\s+--force(\s|$)|git\s+push\s+-f(\s|$)/,
        reason: 'BLOCKED: force push. Use --force-with-lease or rebase properly.',
      },
      {
        test: /chmod\s+-R\s+777/,
        reason: 'BLOCKED: world-writable permissions. Use targeted permissions instead.',
      },
    ];

    for (const rule of rules) {
      if (rule.test.test(command)) {
        console.error('[pre-bash-guard] ' + rule.reason);
        process.exit(2);
      }
    }
    process.exit(0);
  } catch (err) {
    process.exit(0); // fail open — never break the session because of the guard
  }
});

#!/usr/bin/env node
/**
 * PreToolUse(Write|Edit) guard — static analysis before writing files.
 * Warns about common ZCode mistakes: SDK in client code, debug leftovers.
 * Reads the tool input from stdin as JSON: { tool_name, tool_input: { file_path, content? } }
 */
let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => (raw += chunk));
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(raw || '{}');
    const filePath = (input.tool_input && input.tool_input.file_path) || '';
    const content =
      (input.tool_input && (input.tool_input.content || input.tool_input.new_string)) || '';

    const warnings = [];

    // 1. SDK in client code — critical boundary violation
    if (/\.tsx?$/.test(filePath) && content.includes("'use client'") === false) {
      // server files are fine
    }
    if (filePath && /\.tsx?$/.test(filePath) && /z-ai-web-dev-sdk/.test(content)) {
      const hasUseClient = content.split('\n').some((l) => l.trim() === "'use client'" || l.trim() === '"use client"');
      if (hasUseClient) {
        warnings.push('CRITICAL: z-ai-web-dev-sdk imported in a CLIENT component. Move to src/app/api/*/route.ts.');
      }
    }

    // 2. Absolute localhost fetch — gateway rule violation
    if (/fetch\(\s*[`'"]https?:\/\/(localhost|127\.0\.0\.1)/.test(content)) {
      warnings.push('GATEWAY: absolute localhost fetch detected. Use relative URLs; non-3000 ports need ?XTransformPort=<port>.');
    }

    // 3. Debug leftovers
    const consoleLogCount = (content.match(/console\.log\(/g) || []).length;
    if (consoleLogCount > 5) {
      warnings.push(`HYGIENE: ${consoleLogCount} console.log calls in one write — consider cleaning before commit.`);
    }

    if (/@ts-ignore/.test(content)) {
      warnings.push('TYPES: @ts-ignore detected. Fix the type instead of silencing it.');
    }

    if (warnings.length > 0) {
      console.error('[pre-write-guard] Warnings for ' + filePath + ':');
      warnings.forEach((w) => console.error('  - ' + w));
      // Non-blocking: warnings only. Exit 0 to allow the write.
    }
    process.exit(0);
  } catch (err) {
    // Never block work because the guard itself failed.
    process.exit(0);
  }
});

#!/usr/bin/env node
/**
 * SessionStart hook — restore working context at session start.
 * Prints the tail of worklog.md so the agent starts with full memory.
 * Set WORKLOG_PATH to override the default location.
 */
const fs = require('fs');
const path = require('path');

const worklogPath =
  process.env.WORKLOG_PATH ||
  path.join(process.cwd(), 'worklog.md');

try {
  if (!fs.existsSync(worklogPath)) {
    console.log(
      '[session-start] No worklog.md found. First session? Consider creating one for cross-session memory.'
    );
    process.exit(0);
  }

  const content = fs.readFileSync(worklogPath, 'utf8');
  const lines = content.split('\n');
  const tail = lines.slice(-60).join('\n'); // last section is the freshest

  console.log('[session-start] Restoring context from worklog.md (tail):');
  console.log('---');
  console.log(tail);
  console.log('---');
  console.log(
    '[session-start] Read the full worklog.md if you need earlier history. Update it when you finish work.'
  );
} catch (err) {
  console.error(`[session-start] Failed to read worklog: ${err.message}`);
}

#!/usr/bin/env node
/**
 * Stop hook — checkpoint reminder when the agent finishes responding.
 * Checks whether worklog.md was touched in this session; nudges if not.
 */
const fs = require('fs');
const path = require('path');

const worklogPath = process.env.WORKLOG_PATH || path.join(process.cwd(), 'worklog.md');

try {
  if (!fs.existsSync(worklogPath)) {
    console.log(
      '[stop-checkpoint] Reminder: no worklog.md updates this project yet. Run /checkpoint to persist session state.'
    );
    process.exit(0);
  }

  const stat = fs.statSync(worklogPath);
  const ageHours = (Date.now() - stat.mtimeMs) / (1000 * 60 * 60);

  if (ageHours > 8) {
    console.log(
      '[stop-checkpoint] worklog.md is over 8 hours stale. If this session did meaningful work, append a checkpoint (see /checkpoint).'
    );
  } else {
    console.log('[stop-checkpoint] worklog.md is fresh. Good session hygiene.');
  }
  process.exit(0);
} catch (err) {
  process.exit(0);
}

